@@ -3,6 +3,7 @@
 ## Unreleased

 - Faster tag lookup.
+- Fix `daysLeft` and `isExpired` to count UTC calendar days, so an item expiring tomorrow shows 1 day left at any time of day.

 ## 1.4.2 - 2026-09-30

diff --git a/src/expiry.js b/src/expiry.js
index 0a7b267..93e685a 100644
--- a/src/expiry.js
+++ b/src/expiry.js
@@ -2,9 +2,12 @@ import { log } from "./log.js";

 const DAY = 86400000;

-/** Whole days until the item expires (negative once expired). */
+const startOfUtcDay = (t) => Math.floor(new Date(t).getTime() / DAY) * DAY;
+
+/** UTC calendar days from the date of now to the expiry date (negative once expired). */
 export function daysLeft(item, now = Date.now()) {
-  return Math.floor((Date.parse(item.expires) - now) / DAY);
+  const expiry = Date.parse(item.expires);
+  return Math.round((startOfUtcDay(expiry) - startOfUtcDay(now)) / DAY);
 }

 /** True once the item has expired; logs a warning. */
@@ -14,5 +17,5 @@ export function isExpired(item, now = Date.now()) {
     log.warn("item expired", { id: item.id, days: left });
     return true;
   }
-  return left === 0;
+  return false;
 }
